const path = require('path');
const ROOT = path.resolve('/tmp/fake_uploads_root');
const sep = path.sep;

// Edge cases that pattern-matchers often flag but may be safe
const cases = [
  // Null byte injection (Node fs no longer treats null specially since old vulns were fixed, but check resolution)
  'readme.txt\0',
  'readme.txt%00',
  // Backslash on POSIX (should be treated as filename char, not sep)
  '..\\..\\etc\\passwd',
  // Windows-style traversal on posix
  '..\\',
  // Trailing dots
  'readme.txt.',
  '..',
  '.',
  // Long traversal
  'a/'.repeat(50) + '../'.repeat(52) + 'etc/passwd',
  // Encoded traversal that stays lexical
  '....//....//etc/passwd',
  // Mixed
  'public/../../etc/passwd',
];

for (const name of cases) {
  try {
    const candidate = path.resolve(ROOT, name);
    const inside = candidate === ROOT || candidate.startsWith(ROOT + sep);
    console.log(JSON.stringify(name), '=>', candidate, '| inside:', inside);
  } catch (e) {
    console.log(JSON.stringify(name), '=> ERROR:', e.message);
  }
}
EOF
