const path = require('path');
const sep = path.sep;
const ROOT = path.resolve('/tmp/fake_uploads_root');

// The boundary check is LEXICAL (path.resolve doesn't follow symlinks).
// Scenario: attacker controls `name` only (a path string). They cannot create
// symlinks inside uploads unless they have write access there. The function
// `openDownload(name)` only takes a name string from the caller; it does not
// create anything. Whether a symlink attack is possible depends on whether an
// untrusted user can plant a symlink inside ROOT. That's outside this module's
// control and is not a traversal bug in openDownload itself.

// Confirm path.resolve does NOT resolve symlinks (lexical only):
console.log('path.resolve is lexical; does not call realpath/stat.');

// Demonstrate: even a name like 'link' where 'link' is a symlink to /etc/passwd
// would pass the check (it's inside ROOT lexically) and createReadStream would
// follow it. But planting that symlink requires write access inside ROOT.
console.log('Check is lexical-only; symlink-following at open is a separate (out-of-scope) concern requiring write access inside uploads.');
EOF
